<script>function cambiarEstado(id, estado) { $.ajax({url: `{{ url('admin/vestidos') }}/${id}/estado`, type: 'PATCH', data: {_token: '{{ csrf_token() }}', nuevo_estado: estado}, success: r => _alertGeneric('success', 'Actualizado', r.message, 1), error: x => _alertGeneric('error', 'Error', x.responseJSON?.error || 'No fue posible actualizar el estado.')}); }</script>
